    if (__arg(0) != tag) { return 100; }     // 0 番目は第1引数
    if (__arg(1) != n) { return 101; }       // 1 番目は第2引数
    total = 0;
    for (i = 2; i < 2 + n; i = i + 1) {
        total = total + __arg(i);
    }
    return tag * 1000 + total;
}

